// PeekDB returns an already-opened *gorm.DB for role without opening a new connection.
func (r *Registry) PeekDB(role string) *gorm.DB {
	if r == nil {
		return nil
	}
	r.mu.RLock()
	db := r.gormDBs[strings.TrimSpace(role)]
	r.mu.RUnlock()
	return db
}

// EvictRole removes a dynamic connection role (e.g. "master:<key>") from r.gormDBs
// and returns the detached *gorm.DB so the caller can drain and close it safely.
// Built-in static plane roles (cdc, shadow, dest) are never evicted.
func (r *Registry) EvictRole(role string) *gorm.DB {
	role = strings.TrimSpace(role)
	if r == nil || role == "" || role == RoleControlPlane || role == RoleShadow || role == RoleDestination {
		return nil
	}

	r.mu.Lock()
	db := r.gormDBs[role]
	delete(r.gormDBs, role)
	r.mu.Unlock()
	return db
}

